import React from 'react';
import { Link } from 'react-router-dom';

const PropertyCard = ({ property, isFavourite, onToggleFavourite }) => {
  const formatPrice = (price, status) => {
    if (status === 'rent') {
      return `£${price.toLocaleString()}/month`;
    }
    return `£${price.toLocaleString()}`;
  };

  return (
    <div className="property-card-enhanced">
      {/* Hover effect overlay */}
      <div className="card-hover-effect"></div>
      
      <div className="property-image">
        <img 
          src={property.image} 
          alt={property.title}
          className="property-img"
        />
        
        {/* Enhanced badges */}
        <div className="property-badges">
          <span className={`status-badge ${property.status} floating-element`}>
            {property.status === 'sale' ? 'FOR SALE' : 'FOR RENT'}
          </span>
          <span className="type-badge floating-element" style={{ animationDelay: '0.2s' }}>
            {property.type.charAt(0).toUpperCase() + property.type.slice(1)}
          </span>
        </div>
        
        {/* Enhanced favourite button */}
        <button 
          className={`favourite-btn ${isFavourite ? 'active' : ''} floating-element`}
          onClick={() => onToggleFavourite(property.id)}
          aria-label={isFavourite ? "Remove from favourites" : "Add to favourites"}
          style={{ animationDelay: '0.4s' }}
        >
          <span className="heart-animation">
            {isFavourite ? '❤️' : '🤍'}
          </span>
        </button>
      </div>
      
      <div className="property-content">
        <div className="property-header">
          <h3 className="property-title">{property.title}</h3>
          <div className="property-price">
            {formatPrice(property.price, property.status)}
          </div>
        </div>
        
        <p className="property-location">
          <span className="location-icon">📍</span>
          {property.location}
        </p>
        
        {/* Enhanced features with icons */}
        <div className="property-features">
          {[
            { icon: '🛏️', value: `${property.bedrooms} beds` },
            { icon: '🛁', value: `${property.bathrooms} baths` },
            { icon: '📐', value: `${property.sqft.toLocaleString()} sqft` },
            { icon: '⭐', value: 'Premium' }
          ].map((feature, index) => (
            <div key={index} className="feature floating-element" style={{ animationDelay: `${0.1 * index}s` }}>
              <span className="feature-icon">{feature.icon}</span>
              <span className="feature-text">{feature.value}</span>
            </div>
          ))}
        </div>
        
        <div className="property-footer">
          <Link to={`/property/${property.id}`} className="btn btn-view animated-border">
            View Details
          </Link>
          <div className="property-agent">
            <span className="agent-text">Agent: {property.agent}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

const PropertyGrid = ({ properties, favourites, onToggleFavourite }) => {
  if (properties.length === 0) {
    return (
      <div className="no-results">
        <div className="no-results-icon">🏠</div>
        <h3>No properties found</h3>
        <p>Try adjusting your search criteria</p>
      </div>
    );
  }

  return (
    <div className="property-grid">
      {properties.map(property => (
        <PropertyCard
          key={property.id}
          property={property}
          isFavourite={favourites.includes(property.id)}
          onToggleFavourite={onToggleFavourite}
        />
      ))}
    </div>
  );
};

// MAKE SURE THIS DEFAULT EXPORT IS PRESENT
export default PropertyGrid;
